export type MarkId = keyof typeof MARKS;
export const PROVIDER_MARKS: Readonly<Record<MarkId, ProviderMark>> = MARKS;

/**
 * Ids that draw another's mark: the computer brains (the Antigravity CLI Gemini's), Moonshot's API (Kimi), the
 * `anthropic` provider, which people know as Claude, and the accounts' own providers (`provider ?? kind` on the AI
 * accounts' rows): an OpenCode key (`zen`) and a Gemini Enterprise seat (`enterprise`).
 */
const ALIASES: Record<string, MarkId> = {
  anthropic: "claude",
  claude_code: "claude",
  codex: "openai",
  antigravity: "gemini",
  moonshot: "kimi",
  zen: "opencode",
  enterprise: "gemini",
};

/**
 * The mark of a provider, plan, brain or mission executor id (`anthropic`, `zai`, `claude_code`, `claude`), or of a
 * maker a plan names (`Alibaba`, `OpenCode`), in any case;
 * null when there is none, and the caller shows the id's initial.
 */
export function markOf(id: string | null | undefined): MarkId | null {
  if (!id) return null;
  // A plan names some makers as written ("OpenCode", "xAI"), not by an id.
  const key = id.toLowerCase();
  if (Object.hasOwn(PROVIDER_MARKS, key)) return key as MarkId;
  return Object.hasOwn(ALIASES, key) ? (ALIASES[key] ?? null) : null;
}
